  sun.target.position.set(0, 0, 0);
  sun.name = "Sun";
  scene.add(sun);
  scene.add(sun.target);

  // Create ambient light (10% of directional light strength)
  const ambientIntensity = sunIntensity * 0.1;
  const ambient = new AmbientLight(0xffffff, ambientIntensity);
  scene.add(ambient);

