      if (host.isKeyDown("ArrowLeft")) dx -= SPEED * dt;
      if (host.isKeyDown("ArrowUp")) dy += SPEED * dt;
      if (host.isKeyDown("ArrowDown")) dy -= SPEED * dt;

      ship.position.x += dx;
      ship.position.y += dy;

      ship.position.x = MathUtils.clamp(ship.position.x, -LIMIT, LIMIT);
      ship.position.y = MathUtils.clamp(ship.position.y, -LIMIT, LIMIT);
