    clearColor: "#202020",
    update(dt) {
      if (state === "running") {
        elapsedTime += dt;
        if (elapsedTime >= RUN_DURATION) {
          state = "done";
          (beacon.material as any).color.setStyle("#22c55e");
        }
      }
    },
  };
