import { Scene, Mesh } from "three/webgpu";
import { BoxGeometry } from "three";
import { lookAtCamera, startTask, srgb } from "@mtek/benchmarks/baseline-support";
import { MeshBasicNodeMaterial } from "three/webgpu";
